from collections.abc import Callable
import pytest


class TokenBucket:
    def __init__(self, capacity: float, refill_per_sec: float, clock: Callable[[], float]) -> None:
        self.capacity = capacity
        self.refill_per_sec = refill_per_sec
        self._clock = clock
        self._tokens = capacity
        self._updated_at = clock()

    def allow(self, cost: float = 1.0) -> bool:
        now = self._clock()
        elapsed = max(0.0, now - self._updated_at)
        self._updated_at = now
        self._tokens = min(self.capacity, self._tokens + elapsed * self.refill_per_sec)
        if self._tokens >= cost:
            self._tokens -= cost
            return True
        return False


class FakeClock:
    def __init__(self, initial: float = 1000.0) -> None:
        self.now = initial

    def __call__(self) -> float:
        return self.now

    def advance(self, seconds: float) -> None:
        self.now += seconds


@pytest.fixture
def clock() -> FakeClock:
    return FakeClock()


@pytest.mark.parametrize(
    "steps,expected",
    [
        ([(0.0, 1.0), (0.0, 1.0), (0.0, 1.0)], [True, True, False]),
        ([(0.0, 2.0), (0.4, 1.0), (0.1, 1.0)], [True, False, True]),
        ([(0.0, 2.0), (10.0, 2.0), (0.0, 1.0)], [True, True, False]),
    ],
    ids=["burst_exhaustion", "partial_then_full_refill", "refill_clamped_to_capacity"],
)
def test_token_bucket_transitions(
    clock: FakeClock,
    steps: list[tuple[float, float]],
    expected: list[bool],
) -> None:
    bucket = TokenBucket(capacity=2.0, refill_per_sec=2.0, clock=clock)
    outcomes: list[bool] = []
    for dt, cost in steps:
        clock.advance(dt)
        outcomes.append(bucket.allow(cost))
    assert outcomes == expected
