package main

import (
	"fmt"
	"sync"
	"time"
)

type TokenBucket struct {
	mu        sync.Mutex
	capacity  float64
	tokens    float64
	ratePerNs float64
	last      time.Time
}

func NewTokenBucket(ratePerSec, burst float64) *TokenBucket {
	if ratePerSec <= 0 || burst <= 0 {
		panic("ratePerSec and burst must be positive")
	}
	return &TokenBucket{
		capacity:  burst,
		tokens:    burst,
		ratePerNs: ratePerSec / 1e9,
		last:      time.Now(),
	}
}

func (tb *TokenBucket) Allow() bool {
	return tb.AllowN(1)
}

func (tb *TokenBucket) AllowN(n float64) bool {
	if n <= 0 {
		return true
	}
	tb.mu.Lock()
	defer tb.mu.Unlock()

	now := time.Now()
	elapsed := now.Sub(tb.last).Nanoseconds()
	if elapsed > 0 {
		tb.tokens += float64(elapsed) * tb.ratePerNs
		if tb.tokens > tb.capacity {
			tb.tokens = tb.capacity
		}
		tb.last = now
	}
	if tb.tokens < n {
		return false
	}
	tb.tokens -= n
	return true
}

func main() {
	limiter := NewTokenBucket(100, 2)
	fmt.Println(limiter.Allow(), limiter.Allow(), limiter.Allow())
	time.Sleep(15 * time.Millisecond)
	fmt.Println(limiter.Allow())
}
