#!/usr/bin/env python3
import argparse
import json
import os
import signal
import sys
from typing import Any


def extract_path(record: Any, parts: list[str]) -> tuple[bool, Any]:
    cur = record
    for key in parts:
        if isinstance(cur, dict) and key in cur:
            cur = cur[key]
        elif isinstance(cur, list) and key.isdigit():
            idx = int(key)
            if 0 <= idx < len(cur):
                cur = cur[idx]
            else:
                return False, None
        else:
            return False, None
    return True, cur


def main() -> int:
    if hasattr(signal, "SIGPIPE"):
        signal.signal(signal.SIGPIPE, signal.SIG_DFL)

    parser = argparse.ArgumentParser(description="Stream-extract a dotted field from NDJSON.")
    parser.add_argument("field", help="Dot-separated field path, e.g. meta.req.id")
    parser.add_argument("--raw", "-r", action="store_true", help="Unquote string values")
    args = parser.parse_args()
    parts = [p for p in args.field.split(".") if p]

    try:
        for raw_line in sys.stdin:
            line = raw_line.strip()
            if not line:
                continue
            found, val = extract_path(json.loads(line), parts)
            if not found:
                continue
            if args.raw and isinstance(val, str):
                sys.stdout.write(f"{val}\n")
            else:
                sys.stdout.write(f"{json.dumps(val, separators=(',', ':'))}\n")
        sys.stdout.flush()
    except BrokenPipeError:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stderr.fileno())
        os.close(devnull)
        return 0
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
