#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum VarintError {
    UnexpectedEof,
    Overflow,
}

pub fn encode_uvarint(mut value: u64, out: &mut Vec<u8>) -> usize {
    let start = out.len();
    while value >= 0x80 {
        out.push(((value as u8) & 0x7f) | 0x80);
        value >>= 7;
    }
    out.push(value as u8);
    out.len() - start
}

pub fn decode_uvarint(buf: &[u8]) -> Result<(u64, usize), VarintError> {
    let mut result: u64 = 0;
    for (i, &byte) in buf.iter().take(10).enumerate() {
        if i == 9 && byte > 0x01 {
            return Err(VarintError::Overflow);
        }
        result |= ((byte & 0x7f) as u64) << (i * 7);
        if (byte & 0x80) == 0 {
            return Ok((result, i + 1));
        }
    }
    if buf.len() < 10 {
        Err(VarintError::UnexpectedEof)
    } else {
        Err(VarintError::Overflow)
    }
}

#[inline]
pub fn zigzag_encode(n: i64) -> u64 {
    ((n << 1) ^ (n >> 63)) as u64
}

#[inline]
pub fn zigzag_decode(u: u64) -> i64 {
    ((u >> 1) as i64) ^ -((u & 1) as i64)
}

pub fn encode_ivarint(value: i64, out: &mut Vec<u8>) -> usize {
    encode_uvarint(zigzag_encode(value), out)
}

pub fn decode_ivarint(buf: &[u8]) -> Result<(i64, usize), VarintError> {
    let (raw, consumed) = decode_uvarint(buf)?;
    Ok((zigzag_decode(raw), consumed))
}

fn main() {
    let mut buf = Vec::new();
    for &v in &[0_i64, -1, 1, -64, i64::MIN, i64::MAX] {
        buf.clear();
        let written = encode_ivarint(v, &mut buf);
        let (decoded, read) = decode_ivarint(&buf).unwrap();
        assert_eq!((v, written), (decoded, read));
    }
}
