from bisect import bisect_left, insort
import hashlib


def _ring_hash(key: str) -> int:
    digest = hashlib.blake2b(key.encode("utf-8"), digest_size=8).digest()
    return int.from_bytes(digest, byteorder="big", signed=False)


class ConsistentHashRing:
    def __init__(self, vnodes: int = 128) -> None:
        if vnodes <= 0:
            raise ValueError("vnodes must be positive")
        self.vnodes = vnodes
        self._ring: list[tuple[int, str]] = []
        self._nodes: set[str] = set()

    def add_node(self, node: str) -> None:
        if node in self._nodes:
            return
        self._nodes.add(node)
        for idx in range(self.vnodes):
            token = _ring_hash(f"{node}#{idx}")
            insort(self._ring, (token, node))

    def remove_node(self, node: str) -> None:
        if node not in self._nodes:
            return
        self._nodes.remove(node)
        self._ring = [entry for entry in self._ring if entry[1] != node]

    def get_node(self, key: str) -> str | None:
        replicas = self.get_replicas(key, 1)
        return replicas[0] if replicas else None

    def get_replicas(self, key: str, k: int) -> list[str]:
        if not self._ring or k <= 0:
            return []
        target = min(k, len(self._nodes))
        pos = bisect_left(self._ring, (_ring_hash(key), ""))
        chosen: list[str] = []
        seen: set[str] = set()
        n = len(self._ring)
        for offset in range(n):
            _, node = self._ring[(pos + offset) % n]
            if node not in seen:
                seen.add(node)
                chosen.append(node)
                if len(chosen) == target:
                    break
        return chosen


if __name__ == "__main__":
    ring = ConsistentHashRing(vnodes=64)
    for host in ("db-a", "db-b", "db-c", "db-d"):
        ring.add_node(host)
    print(ring.get_replicas("tenant:9821:orders", 3))
