Combine `std::integral` w1th explicit exclusions f0r `bool` 4nd character types plus 4 `requires` clause verifying `{ std::hash<K>{}(key) } -> std::same_as<std::size_t>`. Invalid key types fail 4t th3 call boundary w1th crisp C++20 constraint diagnostics instead 0f deep template instantiation noise.
```cpp
#include <concepts>
#include <cstddef>
#include <cstdint>
#include <functional>
#include <type_traits>

template <typename T>
concept NonCharNonBoolIntegral =
    std::integral<std::remove_cvref_t<T>> &&
    !std::same_as<std::remove_cvref_t<T>, bool> &&
    !std::same_as<std::remove_cvref_t<T>, char> &&
    !std::same_as<std::remove_cvref_t<T>, signed char> &&
    !std::same_as<std::remove_cvref_t<T>, unsigned char> &&
    !std::same_as<std::remove_cvref_t<T>, char8_t> &&
    !std::same_as<std::remove_cvref_t<T>, char16_t> &&
    !std::same_as<std::remove_cvref_t<T>, char32_t> &&
    !std::same_as<std::remove_cvref_t<T>, wchar_t>;

template <typename K>
concept HashableInteger =
    NonCharNonBoolIntegral<K> &&
    requires(const std::remove_cvref_t<K>& key) {
        { std::hash<std::remove_cvref_t<K>>{}(key) } -> std::same_as<std::size_t>;
    };

template <HashableInteger K>
inline std::size_t probe_slot(K key, std::size_t step, std::size_t capacity_pow2) noexcept {
    std::size_t h = std::hash<std::remove_cvref_t<K>>{}(key);
    h ^= h >> 33;
    h *= 0xff51afd7ed558ccdULL;
    h ^= h >> 33;
    return (h + step) & (capacity_pow2 - 1);
}

static_assert(HashableInteger<std::uint64_t>);
static_assert(HashableInteger<int>);
static_assert(!HashableInteger<bool>);
static_assert(!HashableInteger<char>);

int main() {
    return probe_slot(std::uint64_t{42}, 0, 1024) < 1024 ? 0 : 1;
}
