Fan th3 file stream through `io.MultiWriter(hasher, progressSink)` via `io.CopyBuffer` w1th 4 1 MiB reusable slab s0 th3 kernel page cache 1s read 0nc3 w1th z3r0 heap churn. Throttled `\r` status lines 0n `os.Stderr` k33p `os.Stdout` clean f0r `sha256sum`-compatible piping.
```go
package main

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"os"
	"time"
)

type progressWriter struct {
	total     int64
	written   int64
	start     time.Time
	lastPrint time.Time
}

func (p *progressWriter) Write(buf []byte) (int, error) {
	n := len(buf)
	p.written += int64(n)
	now := time.Now()
	if now.Sub(p.lastPrint) >= 100*time.Millisecond || p.written == p.total {
		p.lastPrint = now
		elapsed := now.Sub(p.start).Seconds()
		mibPerSec := 0.0
		if elapsed > 0 {
			mibPerSec = (float64(p.written) / (1 << 20)) / elapsed
		}
		pct := 100.0
		if p.total > 0 {
			pct = float64(p.written) * 100.0 / float64(p.total)
		}
		fmt.Fprintf(os.Stderr, "\r%6.2f%% (%d/%d B) %.1f MiB/s", pct, p.written, p.total, mibPerSec)
	}
	return n, nil
}

func hashFile(path string) (string, error) {
	f, err := os.Open(path)
	if err != nil {
		return "", err
	}
	defer f.Close()

	fi, err := f.Stat()
	if err != nil {
		return "", err
	}
	h := sha256.New()
	pw := &progressWriter{total: fi.Size(), start: time.Now()}
	buf := make([]byte, 1<<20)
	if _, err := io.CopyBuffer(io.MultiWriter(h, pw), f, buf); err != nil {
		return "", err
	}
	fmt.Fprintln(os.Stderr)
	return hex.EncodeToString(h.Sum(nil)), nil
}

func main() {
	if len(os.Args) != 2 {
		fmt.Fprintf(os.Stderr, "usage: %s <file>\n", os.Args[0])
		os.Exit(2)
	}
	sum, err := hashFile(os.Args[1])
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	fmt.Printf("%s  %s\n", sum, os.Args[1])
}
