package ndjson

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
	"io"
)

const (
	InitialScanBuf = 64 * 1024
	DefaultMaxLine = 16 * 1024 * 1024
)

func Consume[T any](r io.Reader, maxLineBytes int, handle func(lineNo int, record T) error) error {
	if maxLineBytes <= 0 {
		maxLineBytes = DefaultMaxLine
	}
	scanner := bufio.NewScanner(r)
	initSize := InitialScanBuf
	if maxLineBytes < initSize {
		initSize = maxLineBytes
	}
	scanner.Buffer(make([]byte, 0, initSize), maxLineBytes)

	lineNo := 0
	for scanner.Scan() {
		lineNo++
		raw := bytes.TrimSpace(scanner.Bytes())
		if len(raw) == 0 {
			continue
		}
		var item T
		if err := json.Unmarshal(raw, &item); err != nil {
			return fmt.Errorf("ndjson line %d decode error: %w", lineNo, err)
		}
		if err := handle(lineNo, item); err != nil {
			return fmt.Errorf("ndjson line %d handler error: %w", lineNo, err)
		}
	}
	if err := scanner.Err(); err != nil {
		return fmt.Errorf("ndjson scan failed after line %d: %w", lineNo, err)
	}
	return nil
}
