```python
import selectors
import socket
from dataclasses import dataclass, field


@dataclass
class ConnState:
    addr: tuple[str, int]
    out_buf: bytearray = field(default_factory=bytearray)
    closing: bool = False


def serve_echo(host: str = "127.0.0.1", port: int = 9009) -> None:
    sel = selectors.DefaultSelector()
    listener = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    listener.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    listener.bind((host, port))
    listener.listen(128)
    listener.setblocking(False)
    sel.register(listener, selectors.EVENT_READ, data=None)

    def close_conn(sock: socket.socket) -> None:
        sel.unregister(sock)
        sock.close()

    try:
        while True:
            for key, mask in sel.select(timeout=1.0):
                if key.data is None:
                    conn, addr = listener.accept()
                    conn.setblocking(False)
                    sel.register(conn, selectors.EVENT_READ, data=ConnState(addr=addr))
                    continue

                sock = key.fileobj
                assert isinstance(sock, socket.socket)
                state: ConnState = key.data

                if mask & selectors.EVENT_READ:
                    try:
                        chunk = sock.recv(4096)
                    except BlockingIOError:
                        chunk = b""
                    except OSError:
                        close_conn(sock)
                        continue
                    if chunk:
                        was_empty = len(state.out_buf) == 0
                        state.out_buf.extend(chunk)
                        if was_empty:
                            sel.modify(sock, selectors.EVENT_READ | selectors.EVENT_WRITE, data=state)
                    else:
                        state.closing = True
                        if not state.out_buf:
                            close_conn(sock)
                            continue
                        sel.modify(sock, selectors.EVENT_WRITE, data=state)

                if (mask & selectors.EVENT_WRITE) and state.out_buf:
                    try:
                        sent = sock.send(state.out_buf)
                        del state.out_buf[:sent]
                    except BlockingIOError:
                        pass
                    except OSError:
                        close_conn(sock)
                        continue
                    if not state.out_buf:
                        if state.closing:
                            close_conn(sock)
                        else:
                            sel.modify(sock, selectors.EVENT_READ, data=state)
    finally:
        sel.close()
        listener.close()
