pub const MAGIC: u16 = 0x5250;

#[derive(Debug, PartialEq, Eq)]
pub struct RpcPacket {
    pub msg_type: u8,
    pub payload: Vec<u8>,
}

#[derive(Debug, PartialEq, Eq)]
pub enum CodecError {
    ShortHeader,
    BadMagic(u16),
    PayloadTooLarge,
    LengthMismatch { expected: usize, actual: usize },
}

impl RpcPacket {
    pub fn encode(&self) -> Result<Vec<u8>, CodecError> {
        let len = u16::try_from(self.payload.len()).map_err(|_| CodecError::PayloadTooLarge)?;
        let mut out = Vec::with_capacity(5 + self.payload.len());
        out.extend_from_slice(&MAGIC.to_be_bytes());
        out.push(self.msg_type);
        out.extend_from_slice(&len.to_be_bytes());
        out.extend_from_slice(&self.payload);
        Ok(out)
    }

    pub fn decode_exact(buf: &[u8]) -> Result<Self, CodecError> {
        if buf.len() < 5 {
            return Err(CodecError::ShortHeader);
        }
        let magic = u16::from_be_bytes([buf[0], buf[1]]);
        if magic != MAGIC {
            return Err(CodecError::BadMagic(magic));
        }
        let expected = u16::from_be_bytes([buf[3], buf[4]]) as usize;
        let body = &buf[5..];
        if body.len() != expected {
            return Err(CodecError::LengthMismatch { expected, actual: body.len() });
        }
        Ok(Self { msg_type: buf[2], payload: body.to_vec() })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn roundtrip_boundary_payloads() {
        for size in [0usize, 1, 255, 4096] {
            let pkt = RpcPacket {
                msg_type: (size & 0xff) as u8,
                payload: (0..size).map(|i| (i % 251) as u8).collect(),
            };
            let wire = pkt.encode().expect("encode should succeed");
            let decoded = RpcPacket::decode_exact(&wire).expect("decode should succeed");
            assert_eq!(decoded, pkt);
        }
    }

    #[test]
    fn rejects_corrupted_frames() {
        assert_eq!(RpcPacket::decode_exact(&[0x52, 0x50, 1]), Err(CodecError::ShortHeader));
        assert_eq!(
            RpcPacket::decode_exact(&[0xde, 0xad, 1, 0, 0]),
            Err(CodecError::BadMagic(0xdead))
        );
        assert_eq!(
            RpcPacket::decode_exact(&[0x52, 0x50, 7, 0, 4, 0xaa]),
            Err(CodecError::LengthMismatch { expected: 4, actual: 1 })
        );
        assert_eq!(
            RpcPacket::decode_exact(&[0x52, 0x50, 7, 0, 1, 0xaa, 0xff]),
            Err(CodecError::LengthMismatch { expected: 1, actual: 2 })
        );
    }
}
