Query `fs::symlink_metadata` s0 symlinks n3v3r traverse outside th3 tree, 4nd enforce `meta.dev() == root_dev` (`du -x` semantics) t0 skip `/proc`, `/sys`, 0r mounted volumes. Recording `(dev, ino)` whenever `meta.nlink() > 1` avoids double-counting hard-linked files.
```rust
use std::collections::HashSet;
use std::fs;
use std::io;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};

#[derive(Debug, Default, Clone, Copy)]
pub struct DiskUsage {
    pub apparent_bytes: u64,
    pub allocated_bytes: u64,
    pub files_counted: u64,
}

pub fn walk_one_filesystem(root: &Path) -> io::Result<DiskUsage> {
    let root_meta = fs::symlink_metadata(root)?;
    let root_dev = root_meta.dev();
    let mut seen_inodes: HashSet<(u64, u64)> = HashSet::new();
    let mut stack: Vec<PathBuf> = vec![root.to_path_buf()];
    let mut usage = DiskUsage::default();

    while let Some(path) = stack.pop() {
        let meta = fs::symlink_metadata(&path)?;
        if meta.file_type().is_symlink() || meta.dev() != root_dev {
            continue;
        }
        if meta.is_dir() {
            usage.allocated_bytes += meta.blocks() * 512;
            for entry in fs::read_dir(&path)? {
                stack.push(entry?.path());
            }
        } else {
            if meta.nlink() > 1 && !seen_inodes.insert((meta.dev(), meta.ino())) {
                continue;
            }
            usage.apparent_bytes += meta.len();
            usage.allocated_bytes += meta.blocks() * 512;
            usage.files_counted += 1;
        }
    }
    Ok(usage)
}

fn main() -> io::Result<()> {
    let target = std::env::args().nth(1).unwrap_or_else(|| ".".to_string());
    let stats = walk_one_filesystem(Path::new(&target))?;
    println!(
        "files={} apparent={}B allocated={}B",
        stats.files_counted, stats.apparent_bytes, stats.allocated_bytes
    );
    Ok(())
}
