```go
package main

import (
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"net/http"
)

const maxUploadBytes = 32 << 20 // 32 MiB

func streamUploadHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	r.Body = http.MaxBytesReader(w, r.Body, maxUploadBytes)
	mr, err := r.MultipartReader()
	if err != nil {
		http.Error(w, "invalid multipart request", http.StatusBadRequest)
		return
	}

	buf := make([]byte, 64<<10)
	hasher := sha256.New()
	var totalBytes int64

	for {
		part, err := mr.NextPart()
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			var maxErr *http.MaxBytesError
			if errors.As(err, &maxErr) {
				http.Error(w, "upload exceeds 32 MiB limit", http.StatusRequestEntityTooLarge)
				return
			}
			http.Error(w, "malformed multipart stream", http.StatusBadRequest)
			return
		}
		if part.FormName() == "artifact" {
			n, copyErr := io.CopyBuffer(hasher, part, buf)
			_ = part.Close()
			if copyErr != nil {
				var maxErr *http.MaxBytesError
				if errors.As(copyErr, &maxErr) {
					http.Error(w, "upload exceeds 32 MiB limit", http.StatusRequestEntityTooLarge)
					return
				}
				http.Error(w, "upload read error", http.StatusBadRequest)
				return
			}
			totalBytes += n
		} else {
			_ = part.Close()
		}
	}

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"bytes":%d,"sha256":"%s"}`, totalBytes, hex.EncodeToString(hasher.Sum(nil)))
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/upload", streamUploadHandler)
	_ = http.ListenAndServe("127.0.0.1:8080", mux)
}
