```rust
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct LatencySummary {
    pub count: u64,
    pub mean_us: f64,
    pub max_us: u64,
}

pub fn summarize_5xx_latencies<'a, I>(lines: I, threshold_us: u64) -> Option<LatencySummary>
where
    I: IntoIterator<Item = &'a str>,
{
    let (count, sum_us, max_us) = lines
        .into_iter()
        .filter_map(|line| {
            let mut parts = line.split_ascii_whitespace();
            let status: u16 = parts.next()?.parse().ok()?;
            let latency_us: u64 = parts.next()?.parse().ok()?;
            (status >= 500 && latency_us >= threshold_us).then_some(latency_us)
        })
        .fold((0_u64, 0_u128, 0_u64), |(cnt, sum, max), lat| {
            (cnt + 1, sum + u128::from(lat), max.max(lat))
        });

    if count == 0 {
        return None;
    }
    Some(LatencySummary {
        count,
        mean_us: (sum_us as f64) / (count as f64),
        max_us,
    })
}

fn main() {
    let sample = [
        "200 450 /healthz",
        "502 18500 /v1/orders",
        "503 42500 /v1/orders",
        "500 200 /v1/cache",
    ];
    let stats = summarize_5xx_latencies(sample, 1000).unwrap();
    assert_eq!(stats.count, 2);
    assert_eq!(stats.max_us, 42500);
}
