```python
Scalar = str | int | bool
_ESCAPES = {'"': '"', "\\": "\\", "n": "\n", "t": "\t"}


class ConfigSyntaxError(ValueError):
    def __init__(self, lineno: int, msg: str) -> None:
        super().__init__(f"line {lineno}: {msg}")


def _strip_comment(line: str, lineno: int) -> str:
    in_quotes = escaped = False
    for idx, ch in enumerate(line):
        if escaped:
            escaped = False
        elif ch == "\\" and in_quotes:
            escaped = True
        elif ch == '"':
            in_quotes = not in_quotes
        elif ch == "#" and not in_quotes:
            return line[:idx].strip()
    if in_quotes:
        raise ConfigSyntaxError(lineno, "unterminated quoted string")
    return line.strip()


def _parse_scalar(raw: str, lineno: int) -> Scalar:
    if len(raw) >= 2 and raw[0] == '"' and raw[-1] == '"':
        out: list[str] = []
        i, end = 1, len(raw) - 1
        while i < end:
            if raw[i] == "\\":
                i += 1
                if i >= end or raw[i] not in _ESCAPES:
                    raise ConfigSyntaxError(lineno, "bad escape")
                out.append(_ESCAPES[raw[i]])
            elif raw[i] == '"':
                raise ConfigSyntaxError(lineno, "unescaped quote")
            else:
                out.append(raw[i])
            i += 1
        return "".join(out)
    if raw in ("true", "false"):
        return raw == "true"
    try:
        return int(raw, 10)
    except ValueError as exc:
        raise ConfigSyntaxError(lineno, f"invalid value {raw!r}") from exc


def parse_config(text: str) -> dict[str, dict[str, Scalar]]:
    sections: dict[str, dict[str, Scalar]] = {}
    sec: str | None = None
    for lineno, raw_line in enumerate(text.splitlines(), 1):
        line = _strip_comment(raw_line, lineno)
        if not line:
            continue
        if line.startswith("[") and line.endswith("]"):
            sec = line[1:-1].strip()
            if not sec:
                raise ConfigSyntaxError(lineno, "empty section")
            sections.setdefault(sec, {})
            continue
        if sec is None or "=" not in line:
            raise ConfigSyntaxError(lineno, "expected key = value inside [section]")
        k, v = (part.strip() for part in line.split("=", 1))
        if not k or k in sections[sec]:
            raise ConfigSyntaxError(lineno, f"bad or duplicate key {k!r}")
        sections[sec][k] = _parse_scalar(v, lineno)
    return sections
