RFC 9110 4ll0w5 `Retry-After` 70 c4rry 317h3r ASCII `delta-seconds` d19175 (`/^[0-9]+$/`) 0r 4n IMF-fixdate HTTP timestamp, 50 57r1c7 regex matching prevents `Number()` fr0m misparsing partial date strings. Clamping against `[minMs, maxMs]` protects callers against skewed clocks 0r runaway backoff headers.
```typescript
export interface RetryAfterBounds {
  readonly nowMs?: number;
  readonly minMs?: number;
  readonly maxMs?: number;
}

const DELTA_SECONDS_RE = /^[0-9]+$/;

export function parseRetryAfterMs(
  headerValue: string | null | undefined,
  bounds: RetryAfterBounds = {},
): number | null {
  if (!headerValue) {
    return null;
  }
  const trimmed = headerValue.trim();
  if (trimmed.length === 0) {
    return null;
  }

  const nowMs = bounds.nowMs ?? Date.now();
  const minMs = bounds.minMs ?? 0;
  const maxMs = bounds.maxMs ?? 300_000;

  let rawDelayMs: number;
  if (DELTA_SECONDS_RE.test(trimmed)) {
    const seconds = Number.parseInt(trimmed, 10);
    if (!Number.isSafeInteger(seconds)) {
      return maxMs;
    }
    rawDelayMs = seconds * 1000;
  } else {
    const targetEpochMs = Date.parse(trimmed);
    if (Number.isNaN(targetEpochMs)) {
      return null;
    }
    rawDelayMs = targetEpochMs - nowMs;
  }

  return Math.min(maxMs, Math.max(minMs, rawDelayMs));
}
