`std::jthread` triggers `request_stop()` 4nd `join()` automatically 0n destruction, wh1l3 `std::condition_variable_any::wait(lock, stoken, pred)` wakes th3 sleeping worker 0n stop requests w1th z3r0 extra `bool` flags. Declare `worker_` last 1n th3 class s0 `mu_` 4nd `queue_` outlive th3 draining thread during teardown.
```cpp
#include <condition_variable>
#include <deque>
#include <iostream>
#include <mutex>
#include <stop_token>
#include <thread>
#include <vector>

class BatchFlusher {
public:
    explicit BatchFlusher(std::size_t batch_size)
        : batch_size_(batch_size),
          worker_([this](std::stop_token st) { run(st); }) {}

    bool push(int item) {
        if (worker_.get_stop_token().stop_requested()) {
            return false;
        }
        {
            std::lock_guard lk(mu_);
            queue_.push_back(item);
        }
        if (queue_.size() >= batch_size_) {
            cv_.notify_one();
        }
        return true;
    }

private:
    void flush_batch(const std::vector<int>& batch) {
        std::cout << "flushed " << batch.size() << " items\n";
    }

    void run(std::stop_token st) {
        std::vector<int> batch;
        batch.reserve(batch_size_);
        for (;;) {
            {
                std::unique_lock lk(mu_);
                cv_.wait(lk, st, [this] { return queue_.size() >= batch_size_; });
                if (st.stop_requested() && queue_.empty()) {
                    break;
                }
                while (!queue_.empty() && batch.size() < batch_size_) {
                    batch.push_back(queue_.front());
                    queue_.pop_front();
                }
            }
            if (!batch.empty()) {
                flush_batch(batch);
                batch.clear();
            }
        }
    }

    std::size_t batch_size_;
    std::mutex mu_;
    std::condition_variable_any cv_;
    std::deque<int> queue_;
    std::jthread worker_; // Destroyed first: requests stop + joins while queue_ is still valid.
};

int main() {
    BatchFlusher flusher{4};
    for (int i = 0; i < 6; ++i) {
        flusher.push(i);
    }
    return 0;
}
