export interface TimeSeriesColumns {
  readonly timestamps: Float64Array;
  readonly values: Float64Array;
}

export function zScoreNormalize(
  values: Float64Array,
  out: Float64Array = new Float64Array(values.length)
): Float64Array {
  const n = values.length;
  if (out.length < n) {
    throw new RangeError("output Float64Array smaller than input");
  }
  if (n === 0) {
    return out;
  }

  let mean = 0.0;
  let m2 = 0.0;
  for (let i = 0; i < n; i++) {
    const x = values[i];
    const delta = x - mean;
    mean += delta / (i + 1);
    m2 += delta * (x - mean);
  }

  const variance = m2 / n;
  if (variance <= 0.0) {
    out.fill(0.0, 0, n);
    return out;
  }

  const invStd = 1.0 / Math.sqrt(variance);
  for (let i = 0; i < n; i++) {
    out[i] = (values[i] - mean) * invStd;
  }
  return out;
}

const series: TimeSeriesColumns = {
  timestamps: Float64Array.from([1000, 2000, 3000, 4000]),
  values: Float64Array.from([10.0, 20.0, 30.0, 40.0]),
};
console.log(zScoreNormalize(series.values, series.values));
