use std::iter::Peekable;
use std::vec::IntoIter;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Token {
    Int(i64),
    Ident(String),
    Op(char),
    LParen,
    RParen,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Expr {
    Int(i64),
    Var(String),
    Unary { op: char, rhs: Box<Expr> },
    Binary { op: char, lhs: Box<Expr>, rhs: Box<Expr> },
}

pub struct Parser {
    tokens: Peekable<IntoIter<Token>>,
}

impl Parser {
    pub fn new(tokens: Vec<Token>) -> Self {
        Self { tokens: tokens.into_iter().peekable() }
    }

    pub fn parse(&mut self) -> Result<Expr, String> {
        let expr = self.parse_bp(0)?;
        if let Some(extra) = self.tokens.peek() {
            return Err(format!("unexpected trailing token: {extra:?}"));
        }
        Ok(expr)
    }

    fn parse_bp(&mut self, min_bp: u8) -> Result<Expr, String> {
        let mut lhs = match self.tokens.next() {
            Some(Token::Int(n)) => Expr::Int(n),
            Some(Token::Ident(s)) => Expr::Var(s),
            Some(Token::LParen) => {
                let inner = self.parse_bp(0)?;
                match self.tokens.next() {
                    Some(Token::RParen) => inner,
                    other => return Err(format!("expected ')', got {other:?}")),
                }
            }
            Some(Token::Op(op @ ('-' | '+'))) => {
                let r_bp = prefix_bp(op);
                let rhs = self.parse_bp(r_bp)?;
                Expr::Unary { op, rhs: Box::new(rhs) }
            }
            other => return Err(format!("expected atom or prefix op, got {other:?}")),
        };

        while let Some(Token::Op(op)) = self.tokens.peek().cloned() {
            let Some((l_bp, r_bp)) = infix_bp(op) else {
                break;
            };
            if l_bp < min_bp {
                break;
            }
            self.tokens.next();
            let rhs = self.parse_bp(r_bp)?;
            lhs = Expr::Binary {
                op,
                lhs: Box::new(lhs),
                rhs: Box::new(rhs),
            };
        }
        Ok(lhs)
    }
}

fn prefix_bp(op: char) -> u8 {
    match op {
        '+' | '-' => 5,
        _ => unreachable!(),
    }
}

fn infix_bp(op: char) -> Option<(u8, u8)> {
    match op {
        '+' | '-' => Some((1, 2)),
        '*' | '/' => Some((3, 4)),
        '^' => Some((8, 7)),
        _ => None,
    }
}
