from collections.abc import Mapping, Sequence


class DependencyCycleError(ValueError):
    def __init__(self, cycles: list[list[str]]) -> None:
        self.cycles = cycles
        formatted = "; ".join(" -> ".join(c) for c in cycles)
        super().__init__(f"dependency cycles detected: {formatted}")


def resolve_build_order(graph: Mapping[str, Sequence[str]]) -> list[str]:
    index_counter = 0
    indices: dict[str, int] = {}
    lowlink: dict[str, int] = {}
    on_stack: set[str] = set()
    stack: list[str] = []
    sccs: list[list[str]] = []

    all_nodes: list[str] = list(graph.keys())
    seen_nodes = set(all_nodes)
    for deps in graph.values():
        for dep in deps:
            if dep not in seen_nodes:
                seen_nodes.add(dep)
                all_nodes.append(dep)

    def strongconnect(node: str) -> None:
        nonlocal index_counter
        indices[node] = index_counter
        lowlink[node] = index_counter
        index_counter += 1
        stack.append(node)
        on_stack.add(node)

        for dep in graph.get(node, ()):
            if dep not in indices:
                strongconnect(dep)
                lowlink[node] = min(lowlink[node], lowlink[dep])
            elif dep in on_stack:
                lowlink[node] = min(lowlink[node], indices[dep])

        if lowlink[node] == indices[node]:
            comp: list[str] = []
            while True:
                w = stack.pop()
                on_stack.remove(w)
                comp.append(w)
                if w == node:
                    break
            sccs.append(comp)

    for target in all_nodes:
        if target not in indices:
            strongconnect(target)

    cycles: list[list[str]] = []
    for comp in sccs:
        if len(comp) > 1:
            cycles.append(list(reversed(comp)))
        elif comp[0] in graph.get(comp[0], ()):
            cycles.append([comp[0], comp[0]])

    if cycles:
        raise DependencyCycleError(cycles)
    return [comp[0] for comp in sccs]
