use std::env;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};
use std::process;
use std::sync::atomic::{AtomicU64, Ordering};
use std::thread;

static NEXT_ID: AtomicU64 = AtomicU64::new(1);

pub struct TempTestWorkspace {
    root: PathBuf,
}

impl TempTestWorkspace {
    pub fn new(prefix: &str) -> io::Result<Self> {
        let base = env::temp_dir();
        let pid = process::id();
        for _ in 0..256 {
            let seq = NEXT_ID.fetch_add(1, Ordering::Relaxed);
            let candidate = base.join(format!("{prefix}-{pid}-{seq}"));
            match fs::create_dir(&candidate) {
                Ok(()) => return Ok(Self { root: candidate }),
                Err(e) if e.kind() == io::ErrorKind::AlreadyExists => continue,
                Err(e) => return Err(e),
            }
        }
        Err(io::Error::new(
            io::ErrorKind::AlreadyExists,
            "exhausted temporary workspace attempts",
        ))
    }

    pub fn path(&self) -> &Path {
        &self.root
    }

    pub fn write_file(&self, rel: impl AsRef<Path>, data: &[u8]) -> io::Result<PathBuf> {
        let full = self.root.join(rel);
        if let Some(parent) = full.parent() {
            fs::create_dir_all(parent)?;
        }
        fs::write(&full, data)?;
        Ok(full)
    }
}

impl Drop for TempTestWorkspace {
    fn drop(&mut self) {
        let keep_on_fail = env::var_os("KEEP_FAILED_TEST_DIRS")
            .map(|v| v == "1")
            .unwrap_or(false);
        if thread::panicking() && keep_on_fail {
            eprintln!("preserving failed test workspace: {}", self.root.display());
            return;
        }
        let _ = fs::remove_dir_all(&self.root);
    }
}
