package wal

import (
	"encoding/binary"
	"errors"
	"fmt"
	"hash/crc32"
	"io"
	"os"
)

const (
	headerSize    = 8
	maxRecordSize = 16 << 20 // 16 MiB guard
)

type Log struct {
	file *os.File
}

func OpenAndRecover(path string) (*Log, [][]byte, error) {
	f, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR, 0o600)
	if err != nil {
		return nil, nil, err
	}
	var (
		records     [][]byte
		validOffset int64
		hdr         [headerSize]byte
	)
	for {
		n, err := io.ReadFull(f, hdr[:])
		if errors.Is(err, io.EOF) && n == 0 {
			break
		}
		if err != nil {
			return truncateTail(f, validOffset, records)
		}
		wantCRC := binary.LittleEndian.Uint32(hdr[0:4])
		length := binary.LittleEndian.Uint32(hdr[4:8])
		if length > maxRecordSize {
			return truncateTail(f, validOffset, records)
		}
		payload := make([]byte, length)
		if _, err := io.ReadFull(f, payload); err != nil {
			return truncateTail(f, validOffset, records)
		}
		if crc32.ChecksumIEEE(payload) != wantCRC {
			return truncateTail(f, validOffset, records)
		}
		validOffset += int64(headerSize) + int64(length)
		records = append(records, payload)
	}
	if _, err := f.Seek(validOffset, io.SeekStart); err != nil {
		_ = f.Close()
		return nil, nil, err
	}
	return &Log{file: f}, records, nil
}

func truncateTail(f *os.File, validOffset int64, records [][]byte) (*Log, [][]byte, error) {
	if err := f.Truncate(validOffset); err != nil {
		_ = f.Close()
		return nil, nil, fmt.Errorf("truncate torn wal: %w", err)
	}
	if err := f.Sync(); err != nil {
		_ = f.Close()
		return nil, nil, err
	}
	if _, err := f.Seek(validOffset, io.SeekStart); err != nil {
		_ = f.Close()
		return nil, nil, err
	}
	return &Log{file: f}, records, nil
}

func (l *Log) Append(payload []byte) error {
	if len(payload) > maxRecordSize {
		return errors.New("record exceeds maxRecordSize")
	}
	buf := make([]byte, headerSize+len(payload))
	binary.LittleEndian.PutUint32(buf[0:4], crc32.ChecksumIEEE(payload))
	binary.LittleEndian.PutUint32(buf[4:8], uint32(len(payload)))
	copy(buf[8:], payload)
	if _, err := l.file.Write(buf); err != nil {
		return err
	}
	return l.file.Sync()
}
