const SUB_BITS: u32 = 4;
const SUB_COUNT: usize = 1 << SUB_BITS; // 16 sub-buckets per octave
const SUB_MASK: u64 = (SUB_COUNT as u64) - 1;
const OCTAVES: usize = 64 - (SUB_BITS as usize) + 1;

pub struct LatencyHistogram {
    counts: Box<[u64]>,
    total: u64,
}

impl LatencyHistogram {
    pub fn new() -> Self {
        Self {
            counts: vec![0u64; OCTAVES * SUB_COUNT].into_boxed_slice(),
            total: 0,
        }
    }

    #[inline]
    fn bucket_index(value: u64) -> usize {
        if value < SUB_COUNT as u64 {
            return value as usize;
        }
        let msb = 63 - value.leading_zeros(); // >= SUB_BITS
        let octave = (msb - SUB_BITS + 1) as usize;
        let shift = msb - SUB_BITS;
        let sub = ((value >> shift) & SUB_MASK) as usize;
        octave * SUB_COUNT + sub
    }

    #[inline]
    fn bucket_upper_bound(idx: usize) -> u64 {
        if idx < SUB_COUNT {
            return idx as u64;
        }
        let octave = idx / SUB_COUNT;
        let sub = (idx % SUB_COUNT) as u64;
        let shift = (octave as u32) - 1;
        let base = ((SUB_COUNT as u64) | sub) << shift;
        base + ((1u64 << shift) - 1)
    }

    #[inline]
    pub fn record(&mut self, value_ns: u64) {
        let idx = Self::bucket_index(value_ns);
        self.counts[idx] += 1;
        self.total += 1;
    }

    pub fn quantile(&self, q: f64) -> Option<u64> {
        if self.total == 0 {
            return None;
        }
        let clamped = q.clamp(0.0, 1.0);
        let target = ((clamped * (self.total as f64)).ceil() as u64).max(1);
        let mut cumulative = 0u64;
        for (idx, &c) in self.counts.iter().enumerate() {
            cumulative += c;
            if cumulative >= target {
                return Some(Self::bucket_upper_bound(idx));
            }
        }
        None
    }
}
