        biased;
        res = &mut primary => match res {
            Ok(val) => return Ok(val),
            Err(err) => Some(err),
        },
        _ = sleep(hedge_delay) => None,
    };

    let backup = make_req(1);
    if primary_early_err.is_some() {
        return backup.await;
    }
    tokio::pin!(backup);

    tokio::select! {
        res1 = &mut primary => match res1 {
            Ok(val) => Ok(val),
            Err(_) => backup.await,
