func inspectBinary(path string) error {
	ef, err := elf.Open(path)
	if err != nil {
		return fmt.Errorf("open elf: %w", err)
	}
	defer ef.Close()

	hasSymtab := ef.Section(".symtab") != nil
	hasDwarf := ef.Section(".debug_info") != nil || ef.Section(".zdebug_info") != nil

	tw := tabwriter.NewWriter(os.Stdout, 0, 4, 2, ' ', 0)
	fmt.Fprintf(tw, "File:\t%s\n", path)
	fmt.Fprintf(tw, "Arch:\t%s (%s)\n", ef.Machine, ef.Class)
	fmt.Fprintf(tw, "Stripped:\tsymtab=%t  dwarf=%t\n", !hasSymtab, !hasDwarf)

	if bi, err := buildinfo.ReadFile(path); err == nil {
		fmt.Fprintf(tw, "GoVersion:\t%s\n", bi.GoVersion)
		for _, s := range bi.Settings {
			if s.Key == "vcs.revision" || s.Key == "-ldflags" || s.Key == "CGO_ENABLED" {
				fmt.Fprintf(tw, "Setting[%s]:\t%s\n", s.Key, s.Value)
			}
		}
	}

	fmt.Fprintln(tw, "\nSECTION\tTYPE\tSIZE_BYTES")
	for _, name := range []string{".text", ".rodata", ".data", ".bss", ".gopclntab"} {
		if sec := ef.Section(name); sec != nil {
			fmt.Fprintf(tw, "%s\t%s\t%d\n", sec.Name, sec.Type, sec.Size)
		}
	}
	return tw.Flush()
}

func main() {
	if len(os.Args) != 2 {
		fmt.Fprintf(os.Stderr, "usage: %s <elf-binary>\n", os.Args[0])
		os.Exit(2)
	}
	if err := inspectBinary(os.Args[1]); err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
}
