export interface SseEvent {
  event: string;
  data: string;
  id: string;
  retry?: number;
}

export class SseStreamParser {
  private decoder = new TextDecoder("utf-8");
  private buffer = "";
  private pendingCr = false;
  private eventType = "";
  private dataLines: string[] = [];
  private lastEventId = "";
  private retryMs: number | undefined;

  public feed(chunk: Uint8Array): SseEvent[] {
    let text = this.decoder.decode(chunk, { stream: true });
    if (this.pendingCr) {
      if (text.startsWith("\n")) {
        text = text.slice(1);
      }
      this.pendingCr = false;
    }
    if (text.endsWith("\r")) {
      this.pendingCr = true;
      text = text.slice(0, -1) + "\n";
    }
    this.buffer += text.replace(/\r\n|\r/g, "\n");

    const emitted: SseEvent[] = [];
    let nlIndex: number;
    while ((nlIndex = this.buffer.indexOf("\n")) !== -1) {
      const line = this.buffer.slice(0, nlIndex);
      this.buffer = this.buffer.slice(nlIndex + 1);
      const ev = this.processLine(line);
      if (ev) emitted.push(ev);
    }
    return emitted;
  }

  private processLine(line: string): SseEvent | null {
    if (line === "") {
      if (this.dataLines.length === 0) {
        this.eventType = "";
        return null;
      }
      const ev: SseEvent = {
        event: this.eventType || "message",
        data: this.dataLines.join("\n"),
        id: this.lastEventId,
        ...(this.retryMs !== undefined ? { retry: this.retryMs } : {}),
      };
      this.eventType = "";
      this.dataLines = [];
      this.retryMs = undefined;
      return ev;
    }
    if (line.startsWith(":")) return null;

    const colon = line.indexOf(":");
    const field = colon === -1 ? line : line.slice(0, colon);
    let value = colon === -1 ? "" : line.slice(colon + 1);
    if (value.startsWith(" ")) value = value.slice(1);

    switch (field) {
      case "event":
        this.eventType = value;
        break;
      case "data":
        this.dataLines.push(value);
        break;
      case "id":
        if (!value.includes("\0")) this.lastEventId = value;
        break;
      case "retry":
        if (/^\d+$/.test(value)) this.retryMs = Number.parseInt(value, 10);
        break;
    }
    return null;
  }
}
