```cpp
#include <cerrno>
#include <cstddef>
#include <cstdint>
#include <sys/socket.h>
#include <vector>

enum class DrainStatus {
    Drained,     // Hit EAGAIN/EWOULDBLOCK; re-arm or wait for next EPOLLET edge
    PeerClosed,  // recv() returned 0 (clean FIN)
    BufferFull,  // Reached max_buffered_bytes backpressure cap
    IoError,     // Fatal errno stored in out_errno
};

struct DrainResult {
    DrainStatus status;
    std::size_t bytes_read;
    int err_code;
};

DrainResult drain_epollet_socket(
    int fd,
    std::vector<uint8_t>& rx_buf,
    std::size_t max_buffered_bytes = 1U << 20
) {
    std::size_t total_read = 0;
    uint8_t scratch[16384];

    while (rx_buf.size() < max_buffered_bytes) {
        const std::size_t budget = max_buffered_bytes - rx_buf.size();
        const std::size_t chunk_cap = budget < sizeof(scratch) ? budget : sizeof(scratch);

        const ssize_t n = ::recv(fd, scratch, chunk_cap, MSG_DONTWAIT);
        if (n > 0) {
            rx_buf.insert(rx_buf.end(), scratch, scratch + n);
            total_read += static_cast<std::size_t>(n);
            continue;
        }
        if (n == 0) {
            return {DrainStatus::PeerClosed, total_read, 0};
        }
        const int e = errno;
        if (e == EINTR) {
            continue;
        }
        if (e == EAGAIN || e == EWOULDBLOCK) {
            return {DrainStatus::Drained, total_read, 0};
        }
        return {DrainStatus::IoError, total_read, e};
    }
    return {DrainStatus::BufferFull, total_read, 0};
}
