#include <array>
#include <cstdint>
#include <span>
#include <string_view>

constexpr std::array<char, 32> encode_trace_id_hex(
    std::span<const uint8_t, 16> bytes
) noexcept {
    std::array<char, 32> out{};
    auto nibble_to_hex = [](uint32_t nib) constexpr noexcept -> char {
        // If nib > 9, (9u - nib) underflows so arithmetic shift yields ~0u, adding 39 ('a' - '0' - 10)
        const uint32_t mask = static_cast<uint32_t>(static_cast<int32_t>(9u - nib) >> 31);
        return static_cast<char>(48u + nib + (mask & 39u));
    };
    for (std::size_t i = 0; i < 16; ++i) {
        const uint32_t b = bytes[i];
        out[2 * i] = nibble_to_hex(b >> 4);
        out[2 * i + 1] = nibble_to_hex(b & 0x0Fu);
    }
    return out;
}

constexpr int32_t decode_hex_nibble(uint8_t c) noexcept {
    // Returns 0..15 for [0-9a-fA-F], or negative value on invalid byte
    const int32_t num = static_cast<int32_t>(c) - '0';
    const int32_t is_num = ((num - 10) & ~num) >> 31; // -1 if '0'..'9', else 0
    const int32_t lower = (static_cast<int32_t>(c) | 0x20) - 'a';
    const int32_t is_alpha = ((lower - 6) & ~lower) >> 31; // -1 if 'a'..'f'/'A'..'F'
    const int32_t val = (is_num & num) | (is_alpha & (lower + 10));
    const int32_t valid = is_num | is_alpha;
    return val | ~valid; // negative (-1) when neither mask matched
}

constexpr bool decode_trace_id_hex(
    std::string_view hex,
    std::span<uint8_t, 16> out
) noexcept {
    if (hex.size() != 32) {
        return false;
    }
    int32_t bad = 0;
    for (std::size_t i = 0; i < 16; ++i) {
        const int32_t hi = decode_hex_nibble(static_cast<uint8_t>(hex[2 * i]));
        const int32_t lo = decode_hex_nibble(static_cast<uint8_t>(hex[2 * i + 1]));
