import * as fs from "node:fs";
import * as path from "node:path";
import * as process from "node:process";

function normalizeText(raw: string): string {
  return raw.replace(/\r\n/g, "\n").trimEnd() + "\n";
}

function formatFirstDiff(expected: string, actual: string, goldenPath: string): string {
  const expLines = expected.split("\n");
  const actLines = actual.split("\n");
  const max = Math.max(expLines.length, actLines.length);
  const out: string[] = [`Golden mismatch in ${goldenPath} (re-run with UPDATE_GOLDEN=1 to bless):`];
  for (let i = 0; i < max; i++) {
    const e = expLines[i];
    const a = actLines[i];
    if (e !== a) {
      out.push(`  line ${i + 1}:`);
      out.push(`    - expected: ${JSON.stringify(e ?? "<EOF>")}`);
      out.push(`    + actual:   ${JSON.stringify(a ?? "<EOF>")}`);
      if (out.length >= 16) break;
    }
  }
  return out.join("\n");
}

export function assertMatchesGolden(goldenPath: string, actualOutput: string): void {
  const normalizedActual = normalizeText(actualOutput);
  const shouldUpdate = process.env.UPDATE_GOLDEN === "1";

  if (shouldUpdate) {
    fs.mkdirSync(path.dirname(goldenPath), { recursive: true });
    const tmpPath = `${goldenPath}.${process.pid}.tmp`;
    fs.writeFileSync(tmpPath, normalizedActual, "utf8");
    fs.renameSync(tmpPath, goldenPath);
    return;
  }

  if (!fs.existsSync(goldenPath)) {
    throw new Error(
      `Missing golden file ${goldenPath}. Run with UPDATE_GOLDEN=1 to initialize.`
    );
  }
  const expected = normalizeText(fs.readFileSync(goldenPath, "utf8"));
  if (expected !== normalizedActual) {
    throw new Error(formatFirstDiff(expected, normalizedActual, goldenPath));
  }
}
