import struct

DNS_HEADER = struct.Struct("!6H")


class DnsWireError(ValueError):
    pass


def encode_qname(domain: str) -> bytes:
    out = bytearray()
    for label in domain.rstrip(".").split("."):
        if not label:
            continue
        raw = label.encode("ascii")
        if len(raw) > 63:
            raise DnsWireError(f"label exceeds 63 octets: {label!r}")
        out.append(len(raw))
        out.extend(raw)
    out.append(0)
    if len(out) > 255:
        raise DnsWireError("encoded domain exceeds 255 octets")
    return bytes(out)


def build_a_query(txid: int, domain: str) -> bytes:
    # Flags 0x0100 = RD (Recursion Desired), QDCOUNT = 1
    header = DNS_HEADER.pack(txid & 0xFFFF, 0x0100, 1, 0, 0, 0)
    question = encode_qname(domain) + struct.pack("!2H", 1, 1)  # QTYPE=A(1), QCLASS=IN(1)
    return header + question


def decode_name(packet: bytes | memoryview, offset: int, max_jumps: int = 16) -> tuple[str, int]:
    n = len(packet)
    labels: list[str] = []
    pos = offset
    next_offset: int | None = None
    jumps = 0
    total_len = 0

    while True:
        if pos >= n:
            raise DnsWireError("truncated DNS name")
        length = packet[pos]
        if length == 0:
            if next_offset is None:
                next_offset = pos + 1
            break
        tag = length & 0xC0
        if tag == 0xC0:
            if pos + 1 >= n:
                raise DnsWireError("truncated compression pointer")
            target = ((length & 0x3F) << 8) | packet[pos + 1]
            if target >= pos:
                raise DnsWireError("forward or self-referential DNS pointer")
            jumps += 1
            if jumps > max_jumps:
                raise DnsWireError("DNS pointer hop limit exceeded")
            if next_offset is None:
                next_offset = pos + 2
            pos = target
        elif tag == 0:
            end = pos + 1 + length
            if end > n:
                raise DnsWireError("truncated DNS label")
            total_len += length + 1
            if total_len > 255:
                raise DnsWireError("decoded name exceeds 255 octets")
            labels.append(bytes(packet[pos + 1 : end]).decode("ascii"))
            pos = end
        else:
            raise DnsWireError(f"reserved label prefix 0x{tag:02x}")

    return ".".join(labels), next_offset
