```typescript
export interface PermitLease {
  release(): void;
}

interface Waiter {
  settled: boolean;
  grant: () => void;
}

export class AsyncSemaphore {
  private permits: number;
  private readonly queue: Waiter[] = [];

  constructor(maxPermits: number) {
    if (!Number.isInteger(maxPermits) || maxPermits < 1) {
      throw new RangeError("maxPermits must be an integer >= 1");
    }
    this.permits = maxPermits;
  }

  public async acquire(signal?: AbortSignal): Promise<PermitLease> {
    signal?.throwIfAborted();
    if (this.permits > 0) {
      this.permits -= 1;
      return this.makeLease();
    }

    return new Promise<PermitLease>((resolve, reject) => {
      const onAbort = (): void => {
        if (waiter.settled) return;
        waiter.settled = true;
        const idx = this.queue.indexOf(waiter);
        if (idx !== -1) this.queue.splice(idx, 1);
        reject(signal?.reason ?? new DOMException("Aborted", "AbortError"));
      };

      const waiter: Waiter = {
        settled: false,
        grant: () => {
          waiter.settled = true;
          signal?.removeEventListener("abort", onAbort);
          resolve(this.makeLease());
        },
      };

      signal?.addEventListener("abort", onAbort, { once: true });
      this.queue.push(waiter);
    });
  }

  private makeLease(): PermitLease {
    let released = false;
    return {
      release: () => {
        if (released) return;
        released = true;
        while (this.queue.length > 0) {
          const next = this.queue.shift()!;
          if (!next.settled) {
            next.grant();
            return;
          }
        }
        this.permits += 1;
      },
    };
  }
}
