import ast
import operator
from collections.abc import Callable, Mapping
from typing import Any

Instruction = tuple[str, Any]
BIN_AST: dict[type[ast.AST], str] = {
    ast.Add: "ADD", ast.Sub: "SUB", ast.Mult: "MUL",
    ast.Lt: "CMP_LT", ast.Eq: "CMP_EQ",
}
BIN_OPS: dict[str, Callable[[Any, Any], Any]] = {
    "ADD": operator.add, "SUB": operator.sub, "MUL": operator.mul,
    "CMP_LT": operator.lt, "CMP_EQ": operator.eq,
}


class BytecodeCompiler(ast.NodeVisitor):
    def __init__(self) -> None:
        self.code: list[Instruction] = []

    def emit(self, op: str, arg: Any = None) -> int:
        self.code.append((op, arg))
        return len(self.code) - 1

    def visit_Constant(self, node: ast.Constant) -> None:
        if not isinstance(node.value, (int, bool)):
            raise TypeError(f"unsupported constant: {node.value!r}")
        self.emit("CONST", node.value)

    def visit_Name(self, node: ast.Name) -> None:
        self.emit("LOAD", node.id)

    def visit_BinOp(self, node: ast.BinOp) -> None:
        self.visit(node.left)
        self.visit(node.right)
        self.emit(BIN_AST[type(node.op)])

    def visit_Compare(self, node: ast.Compare) -> None:
        if len(node.ops) != 1:
            raise TypeError("chained comparisons not supported")
        self.visit(node.left)
        self.visit(node.comparators[0])
        self.emit(BIN_AST[type(node.ops[0])])

    def visit_BoolOp(self, node: ast.BoolOp) -> None:
        jmp = "JMP_IF_FALSE_PEEK" if isinstance(node.op, ast.And) else "JMP_IF_TRUE_PEEK"
        patches: list[int] = []
        for val in node.values[:-1]:
            self.visit(val)
            patches.append(self.emit(jmp, -1))
        self.visit(node.values[-1])
        end_ip = len(self.code)
        for idx in patches:
            self.code[idx] = (self.code[idx][0], end_ip)


def compile_expr(source: str) -> list[Instruction]:
    comp = BytecodeCompiler()
    comp.visit(ast.parse(source, mode="eval").body)
    comp.emit("RET")
    return comp.code


def run_vm(code: list[Instruction], env: Mapping[str, int | bool]) -> int | bool:
    stack: list[int | bool] = []
    ip = 0
    while True:
        op, arg = code[ip]
        ip += 1
        if op == "CONST":
            stack.append(arg)
        elif op == "LOAD":
            stack.append(env[arg])
        elif op in BIN_OPS:
            rhs, lhs = stack.pop(), stack.pop()
            stack.append(BIN_OPS[op](lhs, rhs))
        elif op == "JMP_IF_FALSE_PEEK":
            if not stack[-1]:
                ip = arg
            else:
                stack.pop()
        elif op == "JMP_IF_TRUE_PEEK":
            if stack[-1]:
                ip = arg
            else:
                stack.pop()
        elif op == "RET":
            return stack.pop()
