	return buf, nil
}

func Decode(src []byte) (Record, error) {
	seq, n := binary.Uvarint(src)
	if n <= 0 {
		return Record{}, errors.New("bad seq varint")
	}
	src = src[n:]
	kLen, n := binary.Uvarint(src)
	if n <= 0 || kLen > maxFieldBytes || uint64(len(src)-n) < kLen {
		return Record{}, errors.New("bad key length")
	}
	src = src[n:]
	key := bytes.Clone(src[:kLen])
	src = src[kLen:]
	vLen, n := binary.Uvarint(src)
	if n <= 0 || vLen > maxFieldBytes || uint64(len(src)-n) != vLen {
		return Record{}, errors.New("bad val length or trailing bytes")
	}
	val := bytes.Clone(src[n:])
	return Record{Seq: seq, Key: key, Val: val}, nil
}

func FuzzFrameRoundtrip(f *testing.F) {
	f.Add(uint64(0), []byte(""), []byte(""))
	f.Add(uint64(1<<63-1), []byte("tenant/42"), []byte{0x00, 0xff, 0x7f})

	f.Fuzz(func(t *testing.T, seq uint64, key, val []byte) {
		orig := Record{Seq: seq, Key: key, Val: val}
		wire, err := Encode(orig)
		if len(key) > maxFieldBytes || len(val) > maxFieldBytes {
			if err == nil {
				t.Fatalf("expected error for oversized field")
			}
			return
		}
		if err != nil {
			t.Fatalf("unexpected Encode error: %v", err)
		}
		got, err := Decode(wire)
		if err != nil {
			t.Fatalf("Decode failed on valid wire bytes: %v", err)
		}
		if got.Seq != orig.Seq || !bytes.Equal(got.Key, orig.Key) || !bytes.Equal(got.Val, orig.Val) {
			t.Fatalf("roundtrip mismatch: got %+v, want %+v", got, orig)
		}
	})
}

func FuzzFrameDecodeArbitrary(f *testing.F) {
	f.Add([]byte{0x01, 0x01, 'k', 0x01, 'v'})
	f.Add([]byte{0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x02})
	f.Fuzz(func(t *testing.T, raw []byte) {
		rec, err := Decode(raw)
		if err != nil {
			return
		}
		reencoded, err := Encode(rec)
		if err != nil {
			t.Fatalf("valid decoded record failed Encode: %v", err)
		}
		rec2, err := Decode(reencoded)
		if err != nil || rec2.Seq != rec.Seq || !bytes.Equal(rec2.Key, rec.Key) {
			t.Fatalf("non-idempotent decode->encode->decode")
		}
	})
}
