use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

fn emit_git_rerun_hints() {
    let git_head = Path::new(".git/HEAD");
    if !git_head.exists() {
        return;
    }
    println!("cargo::rerun-if-changed=.git/HEAD");
    if let Ok(contents) = fs::read_to_string(git_head) {
        if let Some(ref_rel) = contents.trim().strip_prefix("ref: ") {
            let ref_path = Path::new(".git").join(ref_rel);
            if ref_path.exists() {
                println!("cargo::rerun-if-changed={}", ref_path.display());
            }
        }
    }
}

fn resolve_git_sha() -> String {
    Command::new("git")
        .args(["rev-parse", "--short=12", "HEAD"])
        .output()
        .ok()
        .filter(|out| out.status.success())
        .and_then(|out| String::from_utf8(out.stdout).ok())
        .map(|s| s.trim().to_owned())
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| "unknown".to_owned())
}

fn generate_opcode_table(def_path: &Path, out_dir: &Path) {
    println!("cargo::rerun-if-changed={}", def_path.display());
    let spec = fs::read_to_string(def_path).unwrap_or_else(|_| "NOP=0x00\nHALT=0xFF\n".to_owned());
    let mut rust_src = String::from("// @generated by build.rs\n");
    for (lineno, raw) in spec.lines().enumerate() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (name, code) = line.split_once('=').unwrap_or_else(|| {
            panic!("malformed opcodes.def at line {}: {}", lineno + 1, line)
        });
        rust_src.push_str(&format!(
            "pub const OP_{}: u8 = {};\n",
            name.trim(),
            code.trim()
        ));
    }
    fs::write(out_dir.join("opcodes_gen.rs"), rust_src).expect("failed writing opcodes_gen.rs");
}

fn main() {
    emit_git_rerun_hints();
    println!("cargo::rustc-env=GIT_COMMIT_SHA={}", resolve_git_sha());

    let out_dir = PathBuf::from(env::var_os("OUT_DIR").expect("OUT_DIR not set"));
    generate_opcode_table(Path::new("spec/opcodes.def"), &out_dir);
}
