```rust
use std::fs;
use std::io::{self, Read, Write};
use std::os::unix::fs::FileTypeExt;
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::Path;
use std::time::Duration;

const MAX_IPC_FRAME: usize = 4 << 20; // 4 MiB

pub fn bind_unix_clean(sock_path: &Path) -> io::Result<UnixListener> {
    match UnixListener::bind(sock_path) {
        Ok(listener) => return Ok(listener),
        Err(e) if e.kind() == io::ErrorKind::AddrInUse => {}
        Err(e) => return Err(e),
    }

    let meta = fs::symlink_metadata(sock_path)?;
    if !meta.file_type().is_socket() {
        return Err(io::Error::new(
            io::ErrorKind::AddrInUse,
            "path exists and is not a unix socket",
        ));
    }

    match UnixStream::connect(sock_path) {
        Ok(_active) => Err(io::Error::new(
            io::ErrorKind::AddrInUse,
            "unix socket is actively owned by a live process",
        )),
        Err(e) if e.kind() == io::ErrorKind::ConnectionRefused => {
            fs::remove_file(sock_path)?;
            UnixListener::bind(sock_path)
        }
        Err(e) => Err(e),
    }
}

pub fn send_frame(stream: &mut UnixStream, payload: &[u8], timeout: Duration) -> io::Result<()> {
    if payload.len() > MAX_IPC_FRAME {
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "IPC frame too large"));
    }
    stream.set_write_timeout(Some(timeout))?;
    let len_hdr = (payload.len() as u32).to_be_bytes();
    stream.write_all(&len_hdr)?;
    stream.write_all(payload)?;
    stream.flush()
}

pub fn recv_frame(stream: &mut UnixStream, timeout: Duration) -> io::Result<Vec<u8>> {
    stream.set_read_timeout(Some(timeout))?;
    let mut len_hdr = [0u8; 4];
    stream.read_exact(&mut len_hdr)?;
    let len = u32::from_be_bytes(len_hdr) as usize;
    if len > MAX_IPC_FRAME {
        return Err(io::Error::new(io::ErrorKind::InvalidData, "IPC frame exceeds cap"));
    }
    let mut buf = vec![0u8; len];
    stream.read_exact(&mut buf)?;
    Ok(buf)
}
