#include <condition_variable>
#include <cstddef>
#include <mutex>
#include <optional>
#include <stdexcept>
#include <stop_token>
#include <utility>
#include <vector>

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity)
        : cap_(capacity), slots_(capacity) {
        if (capacity == 0) {
            throw std::invalid_argument("capacity must be > 0");
        }
    }

    bool push(T item, std::stop_token stoken) {
        std::unique_lock<std::mutex> lk(mu_);
        if (!not_full_.wait(lk, stoken, [this] { return size_ < cap_ || closed_; })) {
            return false; // stop requested
        }
        if (closed_) {
            return false;
        }
        slots_[tail_].emplace(std::move(item));
        tail_ = (tail_ + 1) % cap_;
        ++size_;
        lk.unlock();
        not_empty_.notify_one();
        return true;
    }

    std::optional<T> pop(std::stop_token stoken) {
        std::unique_lock<std::mutex> lk(mu_);
        if (!not_empty_.wait(lk, stoken, [this] { return size_ > 0 || closed_; })) {
            return std::nullopt;
        }
        if (size_ == 0) {
            return std::nullopt;
        }
        T val = std::move(*slots_[head_]);
        slots_[head_].reset();
        head_ = (head_ + 1) % cap_;
        --size_;
        lk.unlock();
        not_full_.notify_one();
        return val;
    }

    void close() noexcept {
        {
            std::lock_guard<std::mutex> lk(mu_);
            closed_ = true;
        }
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    const std::size_t cap_;
    std::vector<std::optional<T>> slots_;
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t size_ = 0;
    bool closed_ = false;
    std::mutex mu_;
    std::condition_variable_any not_empty_;
    std::condition_variable_any not_full_;
};
