#include <array>
#include <cstdint>
#include <optional>
#include <string_view>

struct TraceParent {
    uint8_t version;
    std::array<uint8_t, 16> trace_id;
    std::array<uint8_t, 8> parent_id;
    uint8_t flags;

    [[nodiscard]] constexpr bool sampled() const noexcept {
        return (flags & 0x01U) != 0;
    }
};

constexpr int decode_lower_hex_byte(char hi_c, char lo_c) noexcept {
    auto nib = [](char c) constexpr noexcept -> int {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'f') return (c - 'a') + 10;
        return -1;
    };
    const int hi = nib(hi_c);
    const int lo = nib(lo_c);
    return (hi < 0 || lo < 0) ? -1 : ((hi << 4) | lo);
}

constexpr std::optional<TraceParent> parse_traceparent(std::string_view hdr) noexcept {
    if (hdr.size() != 55 || hdr[2] != '-' || hdr[35] != '-' || hdr[52] != '-') {
        return std::nullopt;
    }
    const int ver = decode_lower_hex_byte(hdr[0], hdr[1]);
    if (ver != 0x00) { // Version 00 requires exact 55-char format; 0xff is invalid
        return std::nullopt;
    }

    TraceParent out{};
    out.version = static_cast<uint8_t>(ver);

    uint8_t trace_nonzero = 0;
    for (std::size_t i = 0; i < 16; ++i) {
        const int b = decode_lower_hex_byte(hdr[3 + 2 * i], hdr[4 + 2 * i]);
        if (b < 0) return std::nullopt;
        out.trace_id[i] = static_cast<uint8_t>(b);
        trace_nonzero |= static_cast<uint8_t>(b);
    }
    if (trace_nonzero == 0) return std::nullopt;

    uint8_t parent_nonzero = 0;
    for (std::size_t i = 0; i < 8; ++i) {
        const int b = decode_lower_hex_byte(hdr[36 + 2 * i], hdr[37 + 2 * i]);
        if (b < 0) return std::nullopt;
        out.parent_id[i] = static_cast<uint8_t>(b);
        parent_nonzero |= static_cast<uint8_t>(b);
    }
    if (parent_nonzero == 0) return std::nullopt;

    const int fl = decode_lower_hex_byte(hdr[53], hdr[54]);
    if (fl < 0) return std::nullopt;
    out.flags = static_cast<uint8_t>(fl);
    return out;
}
