```typescript
export interface BuildTask {
  id: string;
  durationMs: number;
  deps: string[];
}

export interface TaskSchedule {
  earliestStart: number;
  earliestFinish: number;
  latestStart: number;
  slack: number;
}

export interface CpmResult {
  makespanMs: number;
  criticalPath: string[];
  schedule: Map<string, TaskSchedule>;
}

export function analyzeBuildDag(tasks: readonly BuildTask[]): CpmResult {
  const byId = new Map<string, BuildTask>();
  const inDegree = new Map<string, number>();
  const dependents = new Map<string, string[]>();

  for (const t of tasks) {
    byId.set(t.id, t);
    inDegree.set(t.id, t.deps.length);
    if (!dependents.has(t.id)) dependents.set(t.id, []);
  }
  for (const t of tasks) {
    for (const dep of t.deps) {
      if (!byId.has(dep)) throw new Error(`Unknown dependency '${dep}' in '${t.id}'`);
      dependents.get(dep)!.push(t.id);
    }
  }

  const queue: string[] = [];
  for (const [id, deg] of inDegree) {
    if (deg === 0) queue.push(id);
  }
  const topo: string[] = [];
  for (let head = 0; head < queue.length; head++) {
    const u = queue[head]!;
    topo.push(u);
    for (const v of dependents.get(u)!) {
      const nextDeg = inDegree.get(v)! - 1;
      inDegree.set(v, nextDeg);
      if (nextDeg === 0) queue.push(v);
    }
  }
  if (topo.length !== tasks.length) {
    throw new Error("Cycle detected in build dependency graph");
  }

  const es = new Map<string, number>();
  const ef = new Map<string, number>();
  let makespanMs = 0;
  for (const id of topo) {
    const t = byId.get(id)!;
    let start = 0;
    for (const dep of t.deps) start = Math.max(start, ef.get(dep)!);
    const finish = start + t.durationMs;
    es.set(id, start);
    ef.set(id, finish);
    if (finish > makespanMs) makespanMs = finish;
  }

  const ls = new Map<string, number>();
  for (let i = topo.length - 1; i >= 0; i--) {
    const id = topo[i]!;
    const outs = dependents.get(id)!;
    let latestFinish = makespanMs;
    for (const v of outs) latestFinish = Math.min(latestFinish, ls.get(v)!);
    ls.set(id, latestFinish - byId.get(id)!.durationMs);
  }

  const schedule = new Map<string, TaskSchedule>();
  const criticalPath: string[] = [];
  for (const id of topo) {
    const start = es.get(id)!;
    const late = ls.get(id)!;
    const slack = late - start;
    schedule.set(id, { earliestStart: start, earliestFinish: ef.get(id)!, latestStart: late, slack });
    if (slack === 0) criticalPath.push(id);
  }
  return { makespanMs, criticalPath, schedule };
}
