export class StreamIdleTimeoutError extends Error {
  constructor(idleMs: number) {
    super(`Stream stalled with no bytes received for ${idleMs}ms`);
    this.name = "StreamIdleTimeoutError";
  }
}

export async function* streamNdjsonWithIdleTimeout<T = unknown>(
  url: string,
  idleTimeoutMs: number,
  callerSignal?: AbortSignal,
): AsyncGenerator<T, void, undefined> {
  const controller = new AbortController();
  const onCallerAbort = (): void => controller.abort(callerSignal?.reason);
  callerSignal?.addEventListener("abort", onCallerAbort, { once: true });

  let timer: ReturnType<typeof setTimeout> | undefined;
  const armWatchdog = (): void => {
    if (timer !== undefined) clearTimeout(timer);
    timer = setTimeout(() => {
      controller.abort(new StreamIdleTimeoutError(idleTimeoutMs));
    }, idleTimeoutMs);
  };

  try {
    armWatchdog();
    const resp = await fetch(url, { signal: controller.signal });
    if (!resp.ok || !resp.body) {
      throw new Error(`HTTP ${resp.status} or missing response body`);
    }

    const reader = resp.body.getReader();
    const decoder = new TextDecoder("utf-8");
    let buffer = "";

    try {
      while (true) {
        armWatchdog();
        const { value, done } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });

        let nl: number;
        while ((nl = buffer.indexOf("\n")) !== -1) {
          const line = buffer.slice(0, nl).trim();
          buffer = buffer.slice(nl + 1);
          if (line.length > 0) {
            yield JSON.parse(line) as T;
          }
        }
      }
      const tail = (buffer + decoder.decode()).trim();
      if (tail.length > 0) yield JSON.parse(tail) as T;
    } finally {
      reader.releaseLock();
    }
  } finally {
    if (timer !== undefined) clearTimeout(timer);
    callerSignal?.removeEventListener("abort", onCallerAbort);
  }
}
