package supervisor

import (
	"context"
	"errors"
	"fmt"
	"runtime/debug"
	"time"
)

type Policy struct {
	MaxRestarts   int
	BaseBackoff   time.Duration
	MaxBackoff    time.Duration
	HealthyWindow time.Duration
}

func invokeSafe(ctx context.Context, fn func(context.Context) error) (err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("worker panic: %v\n%s", r, debug.Stack())
		}
	}()
	return fn(ctx)
}

func RunSupervised(ctx context.Context, p Policy, worker func(context.Context) error) error {
	failures := 0
	for {
		if err := ctx.Err(); err != nil {
			return nil
		}
		started := time.Now()
		err := invokeSafe(ctx, worker)
		if err == nil || errors.Is(err, context.Canceled) && ctx.Err() != nil {
			return nil
		}

		if time.Since(started) >= p.HealthyWindow {
			failures = 1
		} else {
			failures++
		}
		if failures > p.MaxRestarts {
			return fmt.Errorf("exceeded max restarts (%d): last err: %w", p.MaxRestarts, err)
		}

		delay := p.BaseBackoff << (failures - 1)
		if delay <= 0 || delay > p.MaxBackoff {
			delay = p.MaxBackoff
		}
		timer := time.NewTimer(delay)
		select {
		case <-ctx.Done():
			timer.Stop()
			return nil
		case <-timer.C:
		}
	}
}
