from typing import NamedTuple, Union

Span = tuple[int, int]
ESCAPES = {"n": "\n", "t": "\t", '"': '"', "\\": "\\"}


class Symbol(NamedTuple):
    name: str
    span: Span


class IntLit(NamedTuple):
    value: int
    span: Span


class StrLit(NamedTuple):
    value: str
    span: Span


class SList(NamedTuple):
    items: tuple["Node", ...]
    span: Span


Node = Union[Symbol, IntLit, StrLit, SList]


class SExprSyntaxError(SyntaxError):
    def __init__(self, msg: str, span: Span) -> None:
        self.span = span
        super().__init__(f"{span[0]}:{span[1]}: {msg}")


def parse_sexprs(src: str) -> list[Node]:
    pos, line, col, n = 0, 1, 1, len(src)

    def getc() -> str:
        nonlocal pos, line, col
        ch = src[pos]
        pos += 1
        line, col = (line + 1, 1) if ch == "\n" else (line, col + 1)
        return ch

    def skip_ws() -> None:
        while pos < n:
            if src[pos].isspace():
                getc()
            elif src[pos] == ";":
                while pos < n and getc() != "\n":
                    pass
            else:
                break

    def read_node() -> Node:
        skip_ws()
        span: Span = (line, col)
        if pos >= n or src[pos] == ")":
            raise SExprSyntaxError("unexpected ')' or EOF", span)
        if src[pos] == "(":
            getc()
            items: list[Node] = []
            while True:
                skip_ws()
                if pos >= n:
                    raise SExprSyntaxError("unclosed '('", span)
                if src[pos] == ")":
                    getc()
                    return SList(tuple(items), span)
                items.append(read_node())
        if src[pos] == '"':
            getc()
            buf: list[str] = []
            while pos < n:
                c = getc()
                if c == '"':
                    return StrLit("".join(buf), span)
                if c == "\\":
                    if pos >= n:
                        raise SExprSyntaxError("dangling escape", span)
                    esc = getc()
                    buf.append(ESCAPES.get(esc, esc))
                else:
                    buf.append(c)
            raise SExprSyntaxError("unterminated string", span)
        tok: list[str] = []
        while pos < n and not src[pos].isspace() and src[pos] not in "();\"":
            tok.append(getc())
        raw = "".join(tok)
        return IntLit(int(raw), span) if raw.lstrip("-").isdigit() and raw != "-" else Symbol(raw, span)

    out: list[Node] = []
    while True:
        skip_ws()
        if pos >= n:
            return out
        out.append(read_node())
