#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Edge {
    pub u: usize,
    pub v: usize,
    pub weight: u64,
}

pub struct UnionFind {
    parent: Vec<usize>,
    rank: Vec<u8>,
    components: usize,
}

impl UnionFind {
    pub fn new(n: usize) -> Self {
        Self {
            parent: (0..n).collect(),
            rank: vec![0; n],
            components: n,
        }
    }

    #[inline]
    pub fn find(&mut self, mut x: usize) -> usize {
        while self.parent[x] != x {
            let gp = self.parent[self.parent[x]];
            self.parent[x] = gp;
            x = gp;
        }
        x
    }

    pub fn union(&mut self, a: usize, b: usize) -> bool {
        let mut ra = self.find(a);
        let mut rb = self.find(b);
        if ra == rb {
            return false;
        }
        if self.rank[ra] < self.rank[rb] {
            std::mem::swap(&mut ra, &mut rb);
        }
        self.parent[rb] = ra;
        if self.rank[ra] == self.rank[rb] {
            self.rank[ra] += 1;
        }
        self.components -= 1;
        true
    }
}

pub fn kruskal_mst(num_nodes: usize, mut edges: Vec<Edge>) -> Option<(u64, Vec<Edge>)> {
    if num_nodes <= 1 {
        return Some((0, Vec::new()));
    }
    edges.sort_unstable_by_key(|e| e.weight);
    let mut uf = UnionFind::new(num_nodes);
    let mut mst = Vec::with_capacity(num_nodes - 1);
    let mut total_weight = 0u64;

    for edge in edges {
        if uf.union(edge.u, edge.v) {
            total_weight += edge.weight;
            mst.push(edge);
            if mst.len() == num_nodes - 1 {
                return Some((total_weight, mst));
            }
        }
    }
    None // Graph has > 1 connected component
}
