use std::collections::BTreeMap;
use std::ops::Bound::{Included, Excluded};

#[derive(Default)]
pub struct MemTable {
    seq: u64,
    entries: BTreeMap<Vec<u8>, (u64, Option<Vec<u8>>)>,
}

impl MemTable {
    pub fn put(&mut self, key: Vec<u8>, val: Vec<u8>) {
        self.seq += 1;
        self.entries.insert(key, (self.seq, Some(val)));
    }

    pub fn delete(&mut self, key: Vec<u8>) {
        self.seq += 1;
        self.entries.insert(key, (self.seq, None)); // Tombstone
    }

    pub fn get(&self, key: &[u8]) -> Option<&[u8]> {
        self.entries.get(key).and_then(|(_, v)| v.as_deref())
    }

    pub fn scan(&self, start: &[u8], end: &[u8]) -> Vec<(Vec<u8>, Vec<u8>)> {
        if start >= end {
            return Vec::new();
        }
        self.entries
            .range::<[u8], _>((Included(start), Excluded(end)))
            .filter_map(|(k, (_, v))| v.as_ref().map(|bytes| (k.clone(), bytes.clone())))
            .collect()
    }
}

