from collections import deque
from collections.abc import Iterable, Mapping
from dataclasses import dataclass
from pathlib import PurePosixPath


@dataclass(frozen=True)
class WorkspacePkg:
    name: str
    rel_dir: str       # e.g. 'crates/wal' or 'services/ingestor'
    deps: tuple[str, ...] = ()


GLOBAL_TRIGGERS = {"Cargo.lock", "Cargo.toml", ".github/workflows/ci.yml"}


def select_affected_packages(
    packages: Iterable[WorkspacePkg],
    changed_files: Iterable[str],
) -> list[str]:
    pkg_list = list(packages)
    all_names = sorted(p.name for p in pkg_list)

    # Sort longest path prefix first so nested packages win over parent dirs
    roots = sorted(
        ((PurePosixPath(p.rel_dir), p.name) for p in pkg_list),
        key=lambda item: len(item[0].parts),
        reverse=True,
    )

    rev_deps: dict[str, list[str]] = {p.name: [] for p in pkg_list}
    for p in pkg_list:
        for dep in p.deps:
            if dep in rev_deps:
                rev_deps[dep].append(p.name)

    dirty: set[str] = set()
    for raw_path in changed_files:
        norm = raw_path.strip().lstrip("./")
        if not norm:
            continue
        if norm in GLOBAL_TRIGGERS:
            return all_names
        fpath = PurePosixPath(norm)
        for root_path, pkg_name in roots:
            if fpath == root_path or root_path in fpath.parents:
                dirty.add(pkg_name)
                break

    queue: deque[str] = deque(dirty)
    while queue:
        curr = queue.popleft()
        for consumer in rev_deps.get(curr, ()):
            if consumer not in dirty:
                dirty.add(consumer)
                queue.append(consumer)

    return sorted(dirty)
