	}

	now := time.Now()
	elapsed := now.Sub(tr.lastRefill).Seconds()
	tr.lastRefill = now
	tr.tokens += elapsed * tr.ratePerSec
	if tr.tokens > tr.burst {
		tr.tokens = tr.burst
	}

	if tr.tokens < 1.0 {
		waitDur := time.Duration(((1.0 - tr.tokens) / tr.ratePerSec) * float64(time.Second))
		timer := time.NewTimer(waitDur)
		select {
		case <-tr.ctx.Done():
			timer.Stop()
			return 0, tr.ctx.Err()
		case t := <-timer.C:
			tr.tokens += t.Sub(tr.lastRefill).Seconds() * tr.ratePerSec
			tr.lastRefill = t
		}
	}

	maxRead := int(tr.tokens)
	if maxRead < 1 {
		maxRead = 1
	}
	if len(p) > maxRead {
		p = p[:maxRead]
	}
	n, err := tr.src.Read(p)
	tr.tokens -= float64(n)
	return n, err
}
