```typescript
export type IrNode =
  | { readonly op: "const"; readonly dst: string; readonly value: number }
  | {
      readonly op: "binop";
      readonly dst: string;
      readonly kind: "add" | "sub" | "mul";
      readonly lhs: string;
      readonly rhs: string;
    }
  | {
      readonly op: "branch";
      readonly cond: string;
      readonly thenBlock: string;
      readonly elseBlock: string;
    }
  | {
      readonly op: "phi";
      readonly dst: string;
      readonly incoming: ReadonlyArray<readonly [block: string, ssaVar: string]>;
    };

export type IrVisitor<R> = {
  readonly [K in IrNode["op"]]: (node: Extract<IrNode, { readonly op: K }>) => R;
};

export function matchIr<R>(node: IrNode, visitor: IrVisitor<R>): R {
  const handler = visitor[node.op] as (n: IrNode) => R;
  return handler(node);
}

// Example compiler analysis pass: collect SSA variables read by an instruction
export function usedSsaVars(inst: IrNode): string[] {
  return matchIr(inst, {
    const: () => [],
    binop: (n) => [n.lhs, n.rhs],
    branch: (n) => [n.cond],
    phi: (n) => n.incoming.map(([, ssaVar]) => ssaVar),
  });
}
